<header class="page-header"><div><p class="eyebrow">External access</p><h1>Create integration token</h1><p>The token will expire in <?= $escape($tokenDays) ?> days and is shown only once.</p></div></header><?php if(isset($errors['form'])): ?><p class="validation-summary"><?= $escape($errors['form']) ?></p><?php endif; ?><form method="post" action="<?= $escape($actionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><label>Name<input name="display_name" value="<?= $escape($values['display_name']??'') ?>" required maxlength="160"></label><fieldset><legend>Scopes</legend><?php foreach($scopes as $key=>$label): ?><label class="checkbox-field"><input type="checkbox" name="scopes[]" value="<?= $escape($key) ?>"<?= in_array($key,$values['scopes']??[],true)?' checked':'' ?>> <?= $escape($label) ?></label><?php endforeach; ?></fieldset><div class="form-actions"><button>Create token</button><a href="<?= $escape($cancelUrl) ?>">Cancel</a></div></form>
